{
  "name": "opencode-claude-auth",
  "version": "3.0.0",
  "description": "OpenCode 2 plugin that uses your Claude Code credentials — no separate login needed.",
  "keywords": [
    "anthropic",
    "auth",
    "claude",
    "opencode",
    "plugin"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/griffinmartin/opencode-claude-auth.git"
  },
  "files": [
    "index.js",
    "opencode-claude-auth.js",
    "dist",
    "installation.md"
  ],
  "type": "module",
  "main": "index.js",
  "module": "index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./index.js"
    },
    "./claude-auth-plugin": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./claude-auth-plugin.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode-claude-auth": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode-claude-auth.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "dependencies": {
    "@opencode/plugin": "2.0.31"
  },
  "devDependencies": {
    "@opencode/client": "2.0.31",
    "@types/node": "^25.5.0",
    "oxfmt": "0.41.0",
    "oxlint": "1.56.0",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "build": "rm -rf dist && tsc && cp src/anthropic-prompt.txt dist/",
    "test": "node --test --experimental-strip-types src/**/*.test.ts scripts/**/*.test.ts",
    "test:isolated": "sh scripts/test-isolated.sh",
    "test:models": "pnpm run build && node scripts/test-models.ts",
    "test:headless": "pnpm run build && node --experimental-strip-types scripts/test-headless.ts",
    "intercept": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts",
    "intercept:all": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts --all",
    "intercept:update": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts --all --update",
    "validate:oauth": "pnpm run build && node --experimental-strip-types scripts/validate-oauth-refresh.ts",
    "lint": "oxlint && oxfmt --check .",
    "lint:fix": "oxlint --fix . && oxfmt --write .",
    "format": "oxfmt --write ."
  }
}
